# Статьи 35–37: чек-листы «что делать, если…» для клиентов и админов – почта, Telegram-бот, печать. 6 языков.
# Ссылки на них – раздел «Wenn etwas nicht geht» на странице learn.html (learn_page.py).
# Поля/параметры сверены с Odoo 18 (mail.mail state/failure_reason, report.url, крон «Mail: Email Queue Manager»).

def _d(title, summary, intro, note, h, quick_ol, admin_ol, causes, send_ul, links_label):
    """h: [быстрая проверка, для администратора, типичные причины, что прислать нам]"""
    return {"title": title, "summary": summary, "body": [
        ("p", intro), ("note", note),
        ("h", h[0]), ("ol", quick_ol),
        ("h", h[1]), ("ol", admin_ol), ("code", "admin"),
        ("h", h[2]), ("table", causes),
        ("h", h[3]), ("ul", send_ul),
        ("links", links_label)]}


